import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "rssTitle", label: "Site title", value: "My Blog" })}${field({ id: "rssUrl", label: "Site URL", value: "https://example.com", full: true })}${textarea({ id: "rssDescription", label: "Description", value: "A static blog about web development." })}${select({ id: "rssLang", label: "Language", value: "en", options: [{ label: "en", value: "en" },{ label: "de", value: "de" },{ label: "fr", value: "fr" },{ label: "es", value: "es" },{ label: "ja", value: "ja" },{ label: "nl", value: "nl" },{ label: "zh", value: "zh" }]})}${textarea({id: "rssItems",label: "Posts (one per line: title|url|date|description)",value: "My First Post|https://example.com/first-post/|2026-01-15|Welcome to my blog.\nSecond Post|https://example.com/second-post/|2026-02-01|Another article about CSS.",help: "Each line: title|url|date|description"})}${field({ id: "rssAuthor", label: "Author", value: "" })}</div>`,generate(root) {const siteTitle = root.querySelector("#rssTitle").value.trim() || "My Blog";const siteUrl = normalizeUrl(root.querySelector("#rssUrl").value);const description = root.querySelector("#rssDescription").value.trim();const lang = root.querySelector("#rssLang").value;const itemsText = root.querySelector("#rssItems").value.trim();const author = root.querySelector("#rssAuthor").value.trim();const escapeXml = (s) => htmlEscape(s).replace(/'/g, "&apos;");const now = new Date().toUTCString();const items = itemsText.split(/\r?\n/).map(l => l.trim()).filter(Boolean).map(line => {const [title, url, date, ...descParts] = line.split("|").map(s => s.trim());if (!title || !url) return "";const desc = descParts.join("|") || "";return ` <item><title>${escapeXml(title)}</title><link>${escapeXml(normalizeUrl(url))}</link><guid isPermaLink="true">${escapeXml(normalizeUrl(url))}</guid>${date ? `<pubDate>${escapeXml(date)}</pubDate>` : ""}${desc ? `<description>${escapeXml(desc)}</description>` : ""}</item>`;}).filter(Boolean).join("\n");const output = `<?xml version="1.0" encoding="UTF-8"?><rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom"><channel><title>${escapeXml(siteTitle)}</title><link>${escapeXml(siteUrl)}</link><description>${escapeXml(description)}</description><language>${escapeXml(lang)}</language>${author ? `<managingEditor>${escapeXml(author)}</managingEditor>` : ""}<lastBuildDate>${now}</lastBuildDate><atom:link href="${escapeXml(siteUrl)}" rel="self" type="application/rss+xml"/>${items}</channel></rss>`;return { output };}};